class Pipeline:
    def __init__(self, directory: Path, sessions=None):
        self.directory = directory.resolve()
        self.plan = read_json(self.directory / "plan.json")
        if "automatic" in self.plan:
            from .automatic import validate_automatic
            validate_automatic(self.plan)
        self.policy = validate_pipeline_policy(read_json(self.directory / "policy.json"))
        if self.plan.get("policy_sha256") != policy_digest(self.policy):
            raise ValueError("Pinned policy changed")
        self.workers, self.excluded = lanes_of(self.plan, self.policy)
        self.sessions = sessions or InteractiveSessions(self.directory, timeout=45)
        self._events_lock = threading.Lock()

    def worker_policy(self, node: str) -> dict:
        return next(item for item in self.policy["workers"] if item["node_id"] == node)

    def failure_drill(self) -> dict | None:
        """The pinned drill: null when prepare skipped it for an excluded lane; the policy's for plans pinned before."""
        return self.plan["failure_drill"] if "failure_drill" in self.plan else self.policy.get("failure_drill")

    def event(self, node: str, status: str, message: str):
        with self._events_lock:
            path = self.directory / "events.jsonl"
            prior = path.read_text().splitlines() if path.exists() else []
            sequence = json.loads(prior[-1])["sequence"] + 1 if prior else 1
            record = {"sequence": sequence, "time": now(), "node": node, "status": status, "message": message}
            with path.open("a") as handle:
                handle.write(json.dumps(record) + "\n")
                handle.flush()
                os.fsync(handle.fileno())

    def launch(self, node: str) -> dict:
        self.event(node, "running", "Launching or reconciling the exact native session")
        try:
            receipt = self.sessions.run(node)
        except Exception as error:
            self.event(node, "blocked", str(error))
            raise
        self.event(node, "interactive", "Awaiting explicit completion signal; idle is not acceptance")
        return receipt

    def launch_reviewer(self, reviewer_id: str, prompt: str, launch_token: str, candidate_commit: str) -> dict:
        node = review_node(reviewer_id)
        self.event(REVIEW, "running", f"Launching the native reviewer session {reviewer_id}")
        try:
            receipt = self.sessions.run_reviewer(reviewer_id, prompt, launch_token, candidate_commit)
        except Exception as error:
            self.event(REVIEW, "blocked", f"Reviewer {reviewer_id}: {error}")
            raise
        self.event(REVIEW, "interactive", f"Reviewer {reviewer_id} session {receipt['session_id']} launched; awaiting {node}.completion.json")
        if (self.directory / "terminals.json").exists() and os.environ.get("HERDR_ENV") == "1":
            # The pane is a convenience for the operator; its absence never fails the review. The
            # session is launched by now, so a Ctrl-C here is recorded, then propagated as an
            # interruption (the review node keeps the running session), never as a launch failure.
            try:
                attach_reviewer_panel(self.sessions)
                self.event(REVIEW, "running", f"Reviewer {reviewer_id} pane attached")
            except BaseException as error:
                self.event(REVIEW, "running", f"Reviewer {reviewer_id} pane not attached: {str(error) or type(error).__name__}")
                if not isinstance(error, Exception):
                    raise
        return receipt

    def reconcile_reviewer(self, reviewer_id: str = DEFAULT_REVIEWER) -> dict:
        """Bind the session an interrupted reviewer launch produced; nothing is launched."""
        node = review_node(reviewer_id)
        path = self.directory / f"{node}.interactive.json"
        if not path.exists():
            raise RuntimeError(f"No durable launch intent for reviewer {reviewer_id}; cannot reconcile without potentially launching a new reviewer")
        self.event(REVIEW, "running", f"Reconciling the interrupted launch of reviewer {reviewer_id}; nothing is relaunched")
        try:
            receipt = self.sessions.reconcile(node, path, read_json(path))
        except Exception as error:
            self.event(REVIEW, "blocked", f"Reviewer {reviewer_id}: {error}")
            raise
        self.event(REVIEW, "interactive", f"Reviewer {reviewer_id} session {receipt['session_id']} reconciled; awaiting {node}.completion.json")
        return receipt

    def stop_row(self, node: str, rows: list[dict]) -> dict | None:
        """locate for a stop, under the controller's rule for an update's respawn gap (UpdateGaps): a bound session the
        listing does not show live yet is listed again every 2 seconds for the grace, then TransientInfraError."""
        gaps = UpdateGaps(self.sessions, self.directory, time.monotonic)
        while True:
            try:
                return gaps.row(node, rows)
            except SessionGap:
                time.sleep(2)
                rows = self.sessions.inventory()

    def stop_session(self, node: str) -> None:
        """Persist native identity before stopping. Never signal guessed/reused PIDs."""
        marker = self.directory / f"{node}.stop.json"
        if marker.exists():
            intent = read_json(marker)
        else:
            row = self.stop_row(node, self.sessions.inventory())
            if row is None:
                raise RuntimeError(f"{node} session missing before stop; reconcile before continuing")
            intent = {"background_id": row["id"], "session_id": row["sessionId"], "pid": row["pid"], "stopped": False, "issued": False}
            save_json(marker, intent)
        if not intent["stopped"]:
            rows = self.sessions.inventory()
            matching = [row for row in rows if row.get("sessionId") == intent["session_id"] and row.get("pid")]
            # A session the listing leaves out (or lists without a PID) counts as stopped only once its stop was issued (an
            # intent recorded before `issued` existed counts as issued); a stop never issued looks through an update's respawn gap.
            if matching or intent.get("issued") is False:
                # Its session UUID listed under another background id is a changed identity, never a gap.
                row = self.stop_row(node, rows) if not matching or any(item.get("id") == intent["background_id"] for item in matching) else None
                if row is None or row["id"] != intent["background_id"] or row["sessionId"] != intent["session_id"]:
                    raise RuntimeError(f"Native {node} session identity changed after stop intent; reconcile manually")
                # The process this stop is for (an update respawns a session under a new PID, same background id and UUID),
                # and that the stop is issued, are recorded before it runs.
                intent.update(pid=row["pid"], issued=True)
                save_json(marker, intent)
                try:
                    result = run_claude([self.sessions.executable, "stop", intent["background_id"]], capture_output=True, text=True, timeout=20)
                except TransientInfraError:
                    intent["issued"] = False  # Its exec failed for the whole grace: nothing ran, the stop is still owed.
                    save_json(marker, intent)
                    raise
                if result.returncode != 0:
                    raise RuntimeError(f"Stop failed for {node}; inspect native session before retrying")
            # Recover stop-before-receipt without issuing another stop command.
            rows = self.sessions.inventory()
            if any(row.get("sessionId") == intent["session_id"] and row.get("pid") for row in rows) or pid_alive(intent["pid"]):
                raise RuntimeError(f"{node} termination is not established; retry after reconciliation")
            intent["stopped"] = True
            save_json(marker, intent)

    def stop_workers(self):
        for node in self.workers:
            self.stop_session(node)
        stopped_ids = {read_json(self.directory / f"{node}.stop.json")["session_id"] for node in self.workers}
        if any(row.get("sessionId") in stopped_ids and row.get("pid") for row in self.sessions.inventory()):
            raise RuntimeError("A stopped worker was restarted; reconcile before snapshot capture")
        self.event("freeze", "stopped", f"Native workers stopped before snapshot capture: {', '.join(self.workers)}")

    def stop_reviewer(self, reviewer_id: str = DEFAULT_REVIEWER):
        self.stop_session(review_node(reviewer_id))
        self.event(REVIEW, "stopped", f"Reviewer {reviewer_id} session stopped; its transcript stays resumable")

    def check_ownership(self, node: str, changed: list[str]) -> None:
        """Every changed path is an exact repository path the lane owns: at freeze, and in a lane repair's snapshot."""
        # Ownership is enforced from the full declared policy: an excluded lane's paths are off-limits to every selected lane.
        excluded_paths = [(other, safe_path(prefix)) for other in self.excluded for prefix in self.worker_policy(other)["owned_paths"]]
        worker = self.worker_policy(node)
        for name in changed:
            safe_path(name)
            for other, prefix in excluded_paths:
                if owns(name, prefix):
                    raise ValueError(f"Ownership violation: {node} edited {name}, owned by excluded lane {other}")
            if not any(owns(name, safe_path(prefix)) for prefix in worker["owned_paths"]):
                raise ValueError(f"{node} edited unowned path: {name}")

    def freeze(self) -> dict:
        record = self.directory / "snapshots.json"
        if record.exists():
            return read_json(record)
        handoffs = {}
        for node in self.workers:
            handoff_path = self.directory / f"{node}.handoff.json"
            if not handoff_path.exists():
                raise ValueError(f"Missing {node} handoff: summary and open_assumptions are required")
            handoff = read_json(handoff_path)
            if set(handoff) != {"summary", "open_assumptions"} or not isinstance(handoff["summary"], str) or not handoff["summary"].strip() or not isinstance(handoff["open_assumptions"], list) or any(not isinstance(item, str) for item in handoff["open_assumptions"]):
                raise ValueError("Malformed worker handoff")
            handoffs[node] = handoff
        self.stop_workers()
        snapshots = {}
        for node in self.workers:
            cwd = Path(self.plan["nodes"][node]["worktree"])
            if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"]:
                raise ValueError("Worker changed HEAD; reconcile commits rather than silently accepting them")
            changed = changed_files(cwd, self.plan["base_commit"])
            self.check_ownership(node, changed)
            for name in changed:
                if (cwd / name).is_symlink():
                    raise ValueError("Symlink changes require manual review before snapshot")
            index = self.directory / f"{node}.snapshot-index"
            if index.exists():
                index.unlink()  # Only our private temporary index, never a user's index.
            env = commit_env()
            env["GIT_INDEX_FILE"] = str(index)
            subprocess.run(["git", "-C", str(cwd), "read-tree", self.plan["base_commit"]], env=env, check=True)
            subprocess.run(["git", "-C", str(cwd), "add", "-A", "--", "."], env=env, check=True)
            tree = subprocess.check_output(["git", "-C", str(cwd), "write-tree"], env=env, text=True).strip()
            # Validate paths from the actual captured tree, including staged renames/deletes.
            captured = git(cwd, "diff-tree", "--no-commit-id", "--no-renames", "--name-only", "-r", self.plan["base_commit"], tree).splitlines()
            if sorted(captured) != changed:
                raise ValueError("Files changed during snapshot; refuse inconsistent evidence")
            commit = self.plan["base_commit"]
            if changed:
                commit = subprocess.check_output(["git", "-C", str(cwd), "-c", "commit.gpgsign=false", "commit-tree", tree,
                                                  "-p", self.plan["base_commit"], "-m", f"Workflow {self.plan['run_id']}: {node}"], env=env, text=True).strip()
            ref = f"refs/workflow/{hashlib.sha256(str(self.directory).encode()).hexdigest()[:16]}/{node}"
            subprocess.run(["git", "-C", str(cwd), "update-ref", ref, commit], check=True)
            receipt = read_json(self.directory / f"{node}.interactive.json")
            snapshots[node] = {"commit": commit, "changed_files": changed, "session_id": receipt["session_id"], **handoffs[node]}
        save_json(record, snapshots)
        self.event("freeze", "succeeded", "Immutable snapshots captured; worker-reported checks are not trusted")
        return snapshots

    def attempt(self, phase: str, node: str) -> int:
        """The lane's current attempt: from the floor of its revision (1, or the one a lane repair set) to the run's limit past it."""
        from .repair import attempt_floor
        path = self.directory / "attempts.json"
        value = read_json(path).get(f"{phase}:{node}", 1) if path.exists() else 1
        floor = attempt_floor(self.directory, phase, node)

        save_json(directory / "plan.json", plan)
        git_worktree(repo, "add", "--detach", str(worktree), revision)
        observed = git(worktree, "rev-parse", "HEAD")
        if observed != revision or git(worktree, "status", "--porcelain"):
            raise RuntimeError(f"Unclean or mismatched initial worktree: {worktree}")
        plan["nodes"][node]["observed_start_commit"] = observed
        save_json(directory / "plan.json", plan)
    return plan


def plan_digest(plan: dict) -> str:
    return hashlib.sha256(json.dumps(plan, sort_keys=True).encode()).hexdigest()


CLAUDE_MISSING_GRACE_SECONDS = 60
UPDATE_ERRNOS = {errno.ENOENT, errno.ENOEXEC, errno.ETXTBSY}


class TransientInfraError(RuntimeError):
    """Claude Code itself is unavailable: an update is replacing the binary, or the background service is restarting.

    It is not a verdict on any session, so the automatic controller stops nothing on it and exits resumable.
    Raised by type at the source (run_claude and friends, the session inventory); never classified from message text.
    """


AUTOUPDATER_OFF = {"DISABLE_AUTOUPDATER": "1"}


def claude_env(env: dict | None = None) -> dict:
    """The environment of every Claude process the controller starts: `env` (default: this process's) with the auto-updater off.

    An update replaces the binary under every running session and restarts the background service, so a run never
    updates Claude Code underneath itself; operators update between runs. A `claude --bg` session is not started by
    the controller: it takes the setting from background_settings.
    """
    return {**(os.environ if env is None else env), **AUTOUPDATER_OFF}


def background_settings() -> list[str]:
    """`--settings` for every `claude --bg` command: the auto-updater off inside the session it starts.

    The short `--bg` helper only hands the session to Claude Code's background service, which starts it with the
    service's own environment plus an allowlist of the helper's (provider, model, config, endpoint and PATH variables),
    so claude_env reaches the session only when this run happened to start the service. The helper's arguments do
    reach it, and settings given there are merged over the user's and the project's.
    """
    return ["--settings", json.dumps({"env": AUTOUPDATER_OFF})]


def wait_out_update(start, grace: float, sleep=None, retry_output=None):
    """`start()` (it runs or starts one `claude` command), repeated while a Claude Code update is in progress.

    An update replaces the installed binary: for a moment the command is missing (ENOENT), half written (ENOEXEC)
    or busy (ETXTBSY), and the exec fails before anything runs. That is repeated every 2 seconds for `grace`
    seconds, then raised as TransientInfraError. `retry_output`, when given, marks a command that only reads (the
    session inventory), so running it again is harmless: an answer it rejects (the restarting background service
    exits nonzero or lists nothing) and a timeout are repeated too, a timeout spending its own seconds of the
    grace; once the grace is spent the last answer is returned, or the timeout raised. Any other failure is raised
    at once, and a command that ran is never repeated without `retry_output`: a launch or a print job never starts twice.
    """
    sleep = sleep or time.sleep
    waited = 0.0
    while True:
        try:
            result = start()
        except OSError as error:
            if not (isinstance(error, FileNotFoundError) or error.errno in UPDATE_ERRNOS):
                raise
            if waited >= grace:
                raise TransientInfraError(f"Claude Code unavailable for {grace:g}s ({error}); an update may be replacing it") from error
        except subprocess.TimeoutExpired as error:
            waited += error.timeout
            if retry_output is None or waited >= grace:
                raise
        else:
            if retry_output is None or not retry_output(result) or waited >= grace:
                return result
        sleep(2)
        waited += 2


def run_claude(command: list[str], *, grace: float = CLAUDE_MISSING_GRACE_SECONDS, sleep=None, retry_output=None,
               **kwargs) -> subprocess.CompletedProcess:
    """`subprocess.run` for a `claude` command, with the auto-updater off, that waits out an update in progress (wait_out_update)."""
    kwargs["env"] = claude_env(kwargs.get("env"))
    return wait_out_update(lambda: subprocess.run(command, **kwargs), grace, sleep, retry_output)


def popen_claude(command: list[str], *, grace: float = CLAUDE_MISSING_GRACE_SECONDS, sleep=None, **kwargs) -> subprocess.Popen:
    """`subprocess.Popen` for a `claude` print job, like run_claude: only a failed exec is repeated, a started job never."""
    kwargs["env"] = claude_env(kwargs.get("env"))
    return wait_out_update(lambda: subprocess.Popen(command, **kwargs), grace, sleep)


def stale_claude_processes(proc: Path = Path("/proc")) -> list[dict]:
    """Running Claude Code processes whose executable an update deleted: `{pid, cwd, command}` each, by pid.

    Such a long-lived session keeps seeing a newer version and reinstalls Claude Code, which makes `claude` briefly
    missing for every other caller. Linux only: without /proc, or for an entry that cannot be read, nothing is reported.
    """
    try:
        entries = [entry for entry in proc.iterdir() if entry.name.isdigit()]
    except OSError:
        return []
    found = []
    for entry in sorted(entries, key=lambda item: int(item.name)):
        try:
            executable = os.readlink(entry / "exe")
            if not executable.endswith(" (deleted)") or "claude" not in executable.lower():
                continue
            cwd = os.readlink(entry / "cwd")
            command = (entry / "cmdline").read_bytes().rstrip(b"\0").replace(b"\0", b" ").decode(errors="replace")
        except OSError:
            continue
        found.append({"pid": int(entry.name), "cwd": cwd, "command": command})
    return found


def stale_claude_warning(proc: Path = Path("/proc")) -> str:
    """One warning naming every stale Claude Code process (stale_claude_processes), or "" when there is none. Never a refusal."""
    stale = stale_claude_processes(proc)
    if not stale:
        return ""
    return "\n".join([f"Warning: {len(stale)} running Claude Code process(es) still run an executable that an update deleted. "
                      "These long-lived sessions keep reinstalling Claude Code, which makes `claude` briefly unavailable to this "
                      "run; restart them before the run:",
                      *(f"  pid {item['pid']} in {item['cwd']}: {item['command']}" for item in stale)])


def terminate(process: subprocess.Popen) -> None:
    try:
        os.killpg(process.pid, signal.SIGTERM)
    except ProcessLookupError:
        return
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        os.killpg(process.pid, signal.SIGKILL)
        process.wait()


class ClaudeSessions:
    def __init__(self, directory: Path, executable: str = "claude", timeout: float = 1800):
        self.directory = directory.resolve()
        self.plan = read_json(self.directory / "plan.json")
        self.workers = plan_workers(self.plan)
        self.excluded = plan_excluded(self.plan)
        if set(self.plan["nodes"]) != set(self.workers):
            raise RuntimeError("Run preparation is incomplete; inspect retained allocation state")
        for node in self.workers:
            info = self.plan["nodes"][node]
            if Path(info["worktree"]).resolve() != self.directory / f"worktree-{node}" or info["observed_start_commit"] != self.plan["base_commit"]:
                raise RuntimeError("Invalid worktree identity/start revision in plan")
        self.executable = executable
        self.timeout = timeout
        self.cancelled = threading.Event()

    def run(self, node: str) -> dict:
        if node not in self.workers:
            raise ValueError("Unknown worker")
        if self.cancelled.is_set():
            raise RuntimeError("Controller cancelled before launch")
        info = self.plan["nodes"][node]
        path = self.directory / f"{node}.json"
        digest = plan_digest(self.plan)
        if path.exists():
            previous = read_json(path)
            if previous["plan_digest"] != digest:
                raise RuntimeError("Run plan changed; refuse result reuse/relaunch")
            if previous["status"] == "succeeded":
                return previous
            raise RuntimeError(f"{node}: existing {previous['status']} session {previous['session_id']}; reconcile before any relaunch")
        cwd = Path(info["worktree"])
        record = {"node_id": node, "session_id": info["session_id"], "attempt": 1,
                  "status": "launching", "pid": None, "plan_digest": digest,
                  "worktree": str(cwd), "base_commit": self.plan["base_commit"]}
        save_json(path, record)  # A crash from here onward must never cause blind relaunch.
        tools = "Read,Glob,Grep,Edit,Write" if self.plan["allow_edits"] else "Read,Glob,Grep"
        command = [self.executable, "--print", "--verbose", "--output-format", "stream-json",
                   "--session-id", info["session_id"], "--safe-mode", "--strict-mcp-config",
                   "--mcp-config", '{"mcpServers":{}}', "--tools", tools,
                   "--permission-mode", "acceptEdits" if self.plan["allow_edits"] else "dontAsk",
                   "--permission-prompts", "none"]
        prompt = ("You are an independent workflow worker. Do not launch other agents, modify shared contract files, "
                  "commit, merge, push or change files outside your assigned worktree. "
                  "Report changed files, checks actually executed, and open assumptions. "
                  "No command execution tools are enabled in this initial session slice.\n\n" + info["task"])
        # Do not let detached workers target the controller's Herdr pane through hooks.
        env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
        env["TMPDIR"] = str(self.directory / f"tmp-{node}")
        Path(env["TMPDIR"]).mkdir(exist_ok=True)
        process = None
        try:
            if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"] or git(cwd, "status", "--porcelain"):
                raise RuntimeError(f"{node}: worktree changed since preparation")
            prompt_path = self.directory / f"{node}.prompt.txt"
            prompt_path.write_text(prompt)
            os.chmod(prompt_path, 0o600)
            # A regular stdin file avoids blocking the controller on a full pipe.
            with prompt_path.open("rb") as input_handle, (self.directory / f"{node}.stream.jsonl").open("wb") as output:
                process = popen_claude(command, cwd=cwd, env=env, stdin=input_handle,
                                       stdout=output, stderr=subprocess.STDOUT, start_new_session=True)
                record.update(status="running", pid=process.pid)
                save_json(path, record)
                import time
                deadline = time.monotonic() + self.timeout
                while process.poll() is None:
                    if self.cancelled.wait(0.1) or time.monotonic() > deadline:
                        terminate(process)
                        raise RuntimeError("Controller cancelled or session timed out; partial work preserved")
                output.flush()
                os.fsync(output.fileno())
            terminal = None
            with (self.directory / f"{node}.stream.jsonl").open(errors="replace") as output:
                for line in output:
                    try:
                        message = json.loads(line)
                    except ValueError:
                        continue
                    if isinstance(message, dict) and message.get("type") == "result":
                        terminal = message
            record["exit_code"] = process.returncode
            if not terminal or terminal.get("session_id") != info["session_id"]:
                raise RuntimeError("Missing or mismatched Claude terminal result; reconciliation required")
            record["claude_result"] = terminal
            if process.returncode != 0 or terminal.get("is_error") is not False or terminal.get("subtype") != "success":
                raise RuntimeError("Claude did not succeed; inspect retained result for usage, permission or execution failure. No automatic retry/provider switch.")
            record["status"] = "succeeded"
        except BaseException as error:
            if process is not None and process.poll() is None:
                terminate(process)
            record.update(status="blocked", error=str(error))
            raise
        finally:
            # Preserve work and a diff even after failure; untracked files remain in the worktree.
            try:
                record["git_status"] = git(cwd, "status", "--porcelain")
                with (self.directory / f"{node}.patch").open("w") as patch:
                    subprocess.run(["git", "-C", str(cwd), "diff", "--binary", self.plan["base_commit"]], stdout=patch, check=True)
            except Exception as error:
                record["evidence_error"] = str(error)
                record["status"] = "blocked"
            save_json(path, record)
        if record["status"] != "succeeded":
            raise RuntimeError("Session evidence capture failed")
        return record

def listed_rows(result: subprocess.CompletedProcess) -> list | None:
    """The rows of one `claude agents --json` answer, or None when it is not a listing: a nonzero exit, or output that is not a JSON list."""
    if result.returncode != 0:
        return None
    try:
        rows = json.loads(result.stdout)
    except (TypeError, ValueError):
        return None
    return rows if isinstance(rows, list) else None


class InteractiveSessions(ClaudeSessions):
    """Native Claude background sessions, not print-mode jobs or Herdr-owned agents."""

    def inventory(self) -> list[dict]:
        """`claude agents --json`. The listing only reads, so while the background service restarts (it exits nonzero,
        prints no list or hangs) it is asked again for the grace; a listing that stays unavailable is TransientInfraError.
        """
        try:
            response = run_claude([self.executable, "agents", "--json"], capture_output=True, text=True, timeout=15,
                                  retry_output=lambda result: listed_rows(result) is None)
        except subprocess.TimeoutExpired as error:
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: {error}") from error
        rows = listed_rows(response)
        if rows is None:
            # Claude Code is unavailable, which says nothing about any session.
            answer = f"exited {response.returncode}" if response.returncode else "printed no session list"
            detail = ((response.stderr or "").strip() or (response.stdout or "").strip())[-300:]
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: "
                                      f"`claude agents --json` {answer}" + (f": {detail}" if detail else ""))
        return rows

    def launch_name(self, node: str) -> str:
        """`workflow-<run>-<lane>`, `workflow-<run>-reviewer` for the default reviewer, `workflow-<run>-reviewer-<id>` otherwise."""
        if node == REVIEW:
            return f"workflow-{self.plan['run_id']}-reviewer"
        if node.startswith("review-"):
            return f"workflow-{self.plan['run_id']}-reviewer-{node[len('review-'):]}"
        return f"workflow-{self.plan['run_id']}-{node}"

    def node_worktree(self, node: str) -> Path:
        """Workers live in the plan's worktrees; every reviewer in the run's shared candidate checkout."""
        if is_review_node(node):
            return self.directory / "review-worktree"
        return Path(self.plan["nodes"][node]["worktree"])

    def locate(self, node: str, rows: list[dict]) -> dict | None:
        path = self.directory / f"{node}.interactive.json"
        if not path.exists():
            return None
        receipt = read_json(path)
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; cannot reconcile session")
        background_id = receipt.get("background_id")
        if not background_id:
            log = self.directory / f"{node}.launch.log"
            if not log.exists():
                return None
            # --bg assigns its own UUID. Bind the ID printed by this launch;
            # never adopt a guessed UUID or a name-only match.
            ids = set(re.findall(r"claude attach ([a-f0-9-]{8,36})\s", log.read_text(errors="replace")))
            if len(ids) != 1:
                raise RuntimeError("Missing/ambiguous native launch ID; reconcile manually")
            background_id = ids.pop()
        matches = [row for row in rows if row.get("id") == background_id]
        if not matches:
            return None
        if len(matches) != 1:
            raise RuntimeError("Ambiguous Claude session identity")
        row = matches[0]
        if row.get("kind") != "background" or Path(row.get("cwd", "")).resolve() != self.node_worktree(node).resolve() or row.get("name") != self.launch_name(node):
            raise RuntimeError("Claude session identity/worktree mismatch")
        if receipt.get("background_id") and row.get("sessionId") != receipt.get("session_id"):
            raise RuntimeError("Native Claude UUID changed; refusing attachment")
        if not isinstance(row.get("sessionId"), str) or not re.fullmatch(r"[a-f0-9-]{36}", row["sessionId"]):
            raise RuntimeError("Missing native Claude UUID")
        # `done` is a finished TURN, not a terminated terminal. Require the
        # native live PID as well; stale registry rows must not imply restart.
        if row.get("state") not in {"idle", "working", "blocked", "done"}:
            raise RuntimeError(f"Session is not attachable: {row.get('state')!r}; reconcile manually")
        pid = row.get("pid")
        if not isinstance(pid, int) or pid <= 0:
            raise RuntimeError("No live native PID; reconcile session before attaching")
        try:
            os.kill(pid, 0)
        except OSError as error:
            raise RuntimeError("Native process is unavailable; refusing implicit restart") from error
        return row

    settle_seconds = 30.0

    def settle(self, node: str) -> dict:
        """Bind the row created by the launch we just issued.

        `claude --bg` exits before the native session has fully registered: the
        inventory row can appear without a PID for a moment. Poll for the exact
        row until it is attachable; identity mismatches still fail immediately
        and nothing is ever launched again from here.
        """
        deadline = time.monotonic() + self.settle_seconds
        while True:
